// ═══ CHECKED: caller CAN recover ═══
// Extend Exception → compiler FORCES caller to handle
public class InsufficientFundsException extends Exception {
    private final BigDecimal balance;
    private final BigDecimal requested;

    public InsufficientFundsException(BigDecimal balance, BigDecimal requested, Throwable cause) {
        super("Balance Rs." + balance + " insufficient for Rs." + requested, cause);
        // ✅ ALWAYS pass cause! Preserves "Caused by:" chain.
        this.balance = balance;
        this.requested = requested;
    }

    public InsufficientFundsException(BigDecimal balance, BigDecimal requested) {
        this(balance, requested, null);  // overload without cause
    }

    public BigDecimal getBalance() { return balance; }
    public BigDecimal getRequested() { return requested; }
    // Caller can: suggest smaller amount, offer overdraft, redirect to deposit page
}

// ═══ UNCHECKED: programming error / unrecoverable ═══
// Extend RuntimeException → compiler does NOT force handling
public class InvalidTradeStateException extends RuntimeException {
    public InvalidTradeStateException(String tradeId, String currentState, String expectedState) {
        super("Trade " + tradeId + " in state " + currentState + ", expected " + expectedState);
    }

    public InvalidTradeStateException(String message, Throwable cause) {
        super(message, cause);  // ✅ preserve cause!
    }
    // Caller CANNOT recover: trade state is corrupted → bug in code
}

// ═══ PRESERVING CAUSE — critical for debugging ═══
try {
    jdbcTemplate.update(sql, params);
} catch (DataAccessException e) {
    // ✅ CORRECT: wrap with cause preserved
    throw new TradeSettlementException("Settlement failed for TRD-001", e);
    // Stack trace shows: TradeSettlementException → Caused by: DataAccessException → Caused by: SQLException
    // Full chain visible! Root cause findable!
}

try {
    jdbcTemplate.update(sql, params);
} catch (DataAccessException e) {
    // ❌ WRONG: cause lost!
    throw new TradeSettlementException("Settlement failed for TRD-001");
    // Stack trace shows ONLY TradeSettlementException — NO "Caused by:"!
    // Was it a connection timeout? Constraint violation? Deadlock? UNKNOWN!
}

// ═══ SWALLOWING — THE WORST ANTI-PATTERN ═══

// ❌ WORST: empty catch — exception DISAPPEARS
try {
    accountService.debit("SAV2001", new BigDecimal("50000"));
    accountService.credit("CUR3001", new BigDecimal("50000"));
} catch (Exception e) {
    // NOTHING! No log, no re-throw, no alert.
    // Debit succeeded, credit failed → Rs.50,000 GONE.
    // No evidence it ever happened. Customer files complaint weeks later.
    // Ops team: "we have no logs of any error."
}

// ❌ ALMOST AS BAD: log and swallow
try {
    accountService.credit("CUR3001", amount);
} catch (Exception e) {
    log.error("Credit failed", e);
    // Logged but NOT re-thrown! Caller thinks credit SUCCEEDED!
    // Return continues normally → customer told "Transfer complete."
    // But credit NEVER happened!
}

// ✅ CORRECT: log AND re-throw (or wrap)
try {
    accountService.credit("CUR3001", amount);
} catch (Exception e) {
    log.error("Credit failed for CUR3001", e);
    throw new TransferException("Transfer failed: credit step", e);
    // Caller KNOWS it failed. Transaction rolled back. Customer told "Failed."
}
