// ─── File: src/test/java/com/bank/custom/CustomExceptionTest.java ───
package com.bank.custom;

import com.bank.custom.exception.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.sql.SQLException;
import static org.assertj.core.api.Assertions.*;

class CustomExceptionTest {

    // CHECKED: caller forced to handle (recoverable)
    @Test
    void checked_callerCanRecover() {
        InsufficientFundsException ex = new InsufficientFundsException(
            new BigDecimal("5000"), new BigDecimal("50000"));

        assertThat(ex).isInstanceOf(Exception.class);            // checked!
        assertThat(ex).isNotInstanceOf(RuntimeException.class);   // NOT unchecked
        assertThat(ex.getBalance()).isEqualByComparingTo("5000");
        assertThat(ex.getShortfall()).isEqualByComparingTo("45000");
        // Caller can say: "You need Rs.45,000 more. Deposit first?"
    }

    // UNCHECKED: programming error (unrecoverable)
    @Test
    void unchecked_programmingError() {
        InvalidTradeStateException ex = new InvalidTradeStateException(
            "TRD-001", "SETTLED", "PENDING");

        assertThat(ex).isInstanceOf(RuntimeException.class);  // unchecked!
        assertThat(ex.getMessage()).contains("SETTLED").contains("PENDING");
        // Nothing caller can do — bug in code.
    }

    // CAUSE PRESERVED: full chain available
    @Test
    void causePreserved_fullChain() {
        SQLException root = new SQLException("Connection refused");
        TransferException ex = new TransferException("Transfer failed", root);

        assertThat(ex.getCause()).isInstanceOf(SQLException.class);
        assertThat(ex.getCause().getMessage()).contains("Connection refused");
        // "Caused by: SQLException: Connection refused" visible in stack trace!
    }

    // CAUSE LOST: anti-pattern
    @Test
    void causeLost_antiPattern() {
        // When you DON'T pass cause:
        RuntimeException withoutCause = new RuntimeException("Transfer failed");
        assertThat(withoutCause.getCause()).isNull();  // NO cause! Root cause LOST!
        // Debugging: WHY did it fail? "Transfer failed" — that's all you know.
    }

    // SWALLOWING: the worst anti-pattern
    @Test
    void swallowing_silentFailure() {
        boolean creditExecuted = false;
        try {
            throw new RuntimeException("Credit failed: column 'amt' not found");
        } catch (Exception e) {
            // ❌ SWALLOWED! No log, no re-throw.
        }
        // creditExecuted is still false — but no one knows!
        assertThat(creditExecuted).isFalse();
        // In production: Rs.50,000 debited, never credited. SILENT LOSS.
    }
}
